import { VERSION } from '../../core/version';
import { download_backup } from '../download';
import {
  all_fonts,
  apply_fonts,
  extract_family,
  load_custom_fonts,
  load_font_id,
  new_font_id,
  save_custom_fonts,
  save_font_id,
  type FontChoice,
} from '../fonts';
import { el, on } from '../dom';
import { icon } from '../icons';
import { get_theme, set_theme, type ThemeMode } from '../theme';
import { load_auto_open, save_auto_open } from '../ui_settings';
import { toast } from '../toast';

/** 设置页：外观、备份、关于。 */

function section(title: string, hint: string, body: HTMLElement): HTMLElement {
  const head = el('div', { class: 'yj-section__head' }, [el('div', { class: 'yj-section__title', text: title })]);
  if (hint) head.append(el('div', { class: 'yj-section__hint', text: hint }));
  return el('div', { class: 'yj-section' }, [head, body]);
}

const THEME_LABELS: Array<{ mode: ThemeMode; label: string }> = [
  { mode: 'light', label: '浅色' },
  { mode: 'dark', label: '深色' },
  { mode: 'system', label: '跟随系统' },
];

export function render_settings(): HTMLElement {
  const container = el('section', { class: 'yj-page' });

  const export_button = el('button', {
    class: 'yj-btn yj-btn--primary yj-export__button',
    text: '导出全部文字收藏',
    attrs: { type: 'button' },
  });
  const export_state = el('div', { class: 'yj-row__meta' });

  on<Event>(export_button, 'click', () => {
    void (async () => {
      export_button.setAttribute('disabled', 'true');
      export_state.textContent = '正在打包';
      try {
        await download_backup();
        export_state.textContent = '已生成备份文件，看看浏览器的下载。';
        toast('备份已导出');
      } catch (error) {
        console.warn('[月季管家] 导出备份失败', error);
        export_state.textContent = '导出失败，稍后再试。';
        toast('导出失败');
      } finally {
        export_button.removeAttribute('disabled');
      }
    })();
  });

  const auto_open_button = el('button', {
    class: 'yj-btn yj-btn--ghost',
    attrs: { type: 'button' },
  });
  on<Event>(auto_open_button, 'click', () => {
    save_auto_open(!load_auto_open());
    render();
  });

  /* ---------------------------------------------------------- 字体 */

  function font_select(which: 'shot' | 'text'): HTMLElement {
    const current = load_font_id(which);
    const select = el('select', { class: 'yj-input yj-font-select' });
    for (const font of all_fonts()) {
      const option = el('option', { attrs: { value: font.id }, text: font.name });
      if (font.id === current) option.setAttribute('selected', 'selected');
      select.append(option);
    }
    on<Event>(select, 'change', () => {
      save_font_id(which, select.value);
      apply_fonts();
      toast('字体已切换');
    });
    return el('label', { class: 'yj-font-row' }, [
      el('span', { class: 'yj-font-row__label', text: which === 'shot' ? '截图' : '文本收藏' }),
      select,
    ]);
  }

  const font_name = el('input', {
    class: 'yj-input yj-font-name',
    attrs: { type: 'text', placeholder: '给这个字体起个名字，例如 月月特供版' },
  });
  const font_css = el('textarea', {
    class: 'yj-textarea yj-font-css',
    attrs: { rows: '4', placeholder: '@import url(...); 或 @font-face { ... }' },
  });
  const font_add = el('button', {
    class: 'yj-btn yj-btn--primary yj-export__button yj-font-add',
    text: '添加字体',
    attrs: { type: 'button' },
  });
  const font_custom_list = el('div', { class: 'yj-card yj-font-list' });

  function add_font(): void {
    const name = font_name.value.trim();
    const css = font_css.value.trim();
    if (!name) {
      toast('先给字体起个名字');
      return;
    }
    if (!css) {
      toast('把字体定义粘进来');
      return;
    }
    const list = load_custom_fonts();
    const entry: FontChoice = {
      id: new_font_id(),
      name,
      css,
      family: extract_family(css),
      builtin: false,
    };
    save_custom_fonts([...list, entry]);
    font_name.value = '';
    font_css.value = '';
    apply_fonts();
    toast(`已添加「${name}」`);
    render();
  }
  on<Event>(font_add, 'click', add_font);

  function render_font_list(): void {
    const list = load_custom_fonts();
    font_custom_list.replaceChildren();
    if (!list.length) {
      font_custom_list.classList.add('yj-card--plain');
      font_custom_list.append(el('div', { class: 'yj-empty__text', text: '还没有自己加的字体。' }));
      return;
    }
    font_custom_list.classList.remove('yj-card--plain');
    for (const font of list) {
      const trash = el('button', {
        class: 'yj-iconbtn yj-row__action yj-row__trash',
        html: icon('trash', 17),
        title: '删除',
        attrs: { type: 'button', 'aria-label': '删除' },
      });
      on<Event>(trash, 'click', () => {
        save_custom_fonts(load_custom_fonts().filter(item => item.id !== font.id));
        apply_fonts();
        toast('已删除字体');
        render();
      });
      font_custom_list.append(
        el('div', { class: 'yj-row' }, [
          el('div', { class: 'yj-row__main' }, [
            el('div', { class: 'yj-row__title', text: font.name }),
            el('div', { class: 'yj-row__meta', text: font.family || '没能从样式里认出字体名' }),
          ]),
          trash,
        ]),
      );
    }
  }

  function render(): void {
    const active = get_theme();
    render_font_list();
    auto_open_button.textContent = load_auto_open()
      ? '切换角色时自动打开收藏库：已开启'
      : '切换角色时自动打开收藏库：已关闭';

    const segments = THEME_LABELS.map(item => {
      const button = el('button', {
        class: `yj-segment${active === item.mode ? ' is-active' : ''}`,
        text: item.label,
        attrs: { type: 'button' },
      });
      on<Event>(button, 'click', () => {
        set_theme(item.mode);
        render();
      });
      return button;
    });

    container.replaceChildren(
      section('外观', '', el('div', { class: 'yj-segmented' }, segments)),
      section(
        '角色卡',
        '',
        el('div', { class: 'yj-card yj-card--plain yj-export' }, [
          auto_open_button,
          el('div', {
            class: 'yj-note',
            text: '开启后，在酒馆里切到某张角色卡时，会自动打开这张卡自己的收藏库。觉得打扰就关掉。',
          }),
        ]),
      ),
      section(
        '字体',
        '截图与文本收藏各选一个',
        el('div', { class: 'yj-card yj-card--plain yj-export' }, [
          font_select('shot'),
          font_select('text'),
          el('div', {
            class: 'yj-note',
            text: '自己加的字体需要把字体定义粘进来（@import 或 @font-face）。注入时只会挑出这两类定义，你粘的其他规则（例如 body { font-family:  }）会被自动丢掉，所以只会作用在本插件里，不会改到酒馆本身的字体。',
          }),
          font_name,
          font_css,
          font_add,
          font_custom_list,
        ]),
      ),
      section(
        '备份',
        '图片不进备份',
        el('div', { class: 'yj-card yj-card--plain yj-export' }, [
          export_button,
          el('div', {
            class: 'yj-note',
            text: '备份里是全部角色的文本收藏、番外指令和设置，不含截图。随时可以自己保存一份留着。',
          }),
          export_state,
        ]),
      ),
      section(
        '关于',
        '',
        el('div', { class: 'yj-note' }, [
          el('div', { text: `月季管家 ${VERSION}` }),
          el('div', { text: '所有内容只存在你自己的浏览器里，不会上传到任何服务器。' }),
        ]),
      ),
    );
  }

  render();
  return container;
}

/** 设置页顶栏用的图标，留着给以后扩展。 */
export const settings_icon = icon('gear', 19);
