import { current_character_key, current_character_name } from '../core/character';
import { avatar_key } from '../core/types';
import { apply_replace_rules, clean_text } from '../core/search';
import { render_shot, resolve_shot_theme, type ShotRenderResult } from '../core/shot_canvas';
import { shot_font_family } from './fonts';
import type { ShotBlock, ShotStyle } from '../core/shot_layout';
import * as store from '../core/store';
import { empty_prefs, type CharacterPrefs } from '../core/types';
import { prompt_dialog } from './dialog';
import { excerpt } from './format';
import { download_blob, shot_filename } from './download';
import { el, on, shadow_layer } from './dom';
import { icon } from './icons';
import { toast } from './toast';
import type { TavernContext } from '../tavern/env';

/**
 * 在聊天页面上直接挑段落。
 *
 * 两种用途共用同一套挑选逻辑：
 * - mode='shot'：把挑中的段落画成一张长图。
 * - mode='text'：把挑中的段落存成一条文本收藏。
 *
 * 做法：进入一个临时模式，在 #chat 上加一个捕获阶段的点击监听，
 * 点中段落就切换选中状态（只加一个 class，不往楼层里插任何节点）。
 * 这样比往每段旁边注入按钮稳得多酒馆的楼层结构随版本变化，注入节点很容易被覆盖或错位。
 *
 * 结构方面的假设都做了兜底：
 * - 楼层优先用 [mesid] 找，找不到再退回 .mes。
 * - 正文容器优先用 .mes_text，找不到就把整个楼层当容器。
 * - 段落在正文容器的直接子元素里找，没有带文字的子元素就把整个容器当一段。
 */

/** 阅读卡片的排版参数，和面板里的截图保持一致。 */
const SHOT_STYLE: ShotStyle = {
  width: 760,
  font_size: 26,
  line_height: 44,
  padding: 44,
  block_gap: 26,
};

const MODE_CLASS = 'yj-para-mode';
const PICKED_CLASS = 'yj-para-picked';

/** 一段被挑中的内容。 */
interface PickedBlock {
  message_id: number;
  is_user: boolean;
  name: string;
  text: string;
}

type Message = { name?: string; mes?: string; is_user?: boolean };

/** 按归属键在角色卡列表里找名字。找不到就退回当前角色的名字。 */
function name_for_key(context: TavernContext | null, key: string): string {
  for (const character of context?.characters ?? []) {
    const avatar = character.avatar;
    if (typeof avatar === 'string' && avatar && avatar_key(avatar) === key) {
      return character.name || '未命名角色';
    }
  }
  return current_character_name(context) || '未指定角色';
}

function chat_container(): HTMLElement | null {
  return document.querySelector<HTMLElement>('#chat');
}

function message_elements(root: HTMLElement): HTMLElement[] {
  const by_id = [...root.querySelectorAll<HTMLElement>('[mesid]')];
  if (by_id.length) return by_id;
  return [...root.querySelectorAll<HTMLElement>('.mes')];
}

function text_container(message: HTMLElement): HTMLElement {
  return message.querySelector<HTMLElement>('.mes_text') ?? message;
}

function paragraph_elements(container: HTMLElement): HTMLElement[] {
  const blocks = [...container.children].filter(
    child => child instanceof HTMLElement && (child.textContent ?? '').trim().length > 0,
  ) as HTMLElement[];
  return blocks.length ? blocks : [container];
}

/** 挑完之后是出图还是存文本。 */
export type PickMode = 'shot' | 'text';

/**
 * 文本收藏时按什么挑。
 * - paragraph：从渲染后的正文里点段落。标签早就被渲染掉了，所以这里用不上清洗标签。
 * - floor：整层收藏。取的是楼层的原始文本，清洗标签在这里生效
 *   <标签> 连同里面的内容一起抹掉，只留标签外的正文。
 */
export type PickUnit = 'paragraph' | 'floor';

export async function start_pick_in_chat(options: {
  context: TavernContext | null;
  mode: PickMode;
  /** 指定存到哪张角色卡名下。不指定就用酒馆里当前这张。 */
  character_key?: string;
  character_name?: string;
  /** 进入模式前先把面板收起来。 */
  on_enter?: () => void;
  /** 退出模式后把工具条放回来。 */
  on_leave?: () => void;
}): Promise<void> {
  if (document.body.classList.contains(MODE_CLASS)) return;

  const maybe_layer = shadow_layer();
  if (!maybe_layer) {
    toast('界面没有挂载，先刷新页面');
    return;
  }
  // 显式声明成非空类型，嵌套函数里 TS 才不会一直提醒可能为空。
  const layer: HTMLElement = maybe_layer;

  const root = chat_container();
  if (!root) {
    toast('没找到聊天区域，先在酒馆里打开一个聊天');
    return;
  }

  const context = options.context;
  const character_key = options.character_key ?? current_character_key(context);
  const character_name = options.character_name ?? name_for_key(context, character_key);

  let prefs: CharacterPrefs = empty_prefs(character_key);
  try {
    prefs = await store.get_prefs(character_key);
  } catch (error) {
    console.warn('[月季管家] 读取截图设置失败，先按默认来', error);
  }

  const messages = message_elements(root).filter(message => (message.textContent ?? '').trim().length > 0);
  if (!messages.length) {
    toast('这个聊天里还没有可以截的正文');
    return;
  }

  /** 元素  它在哪个楼层第几段。 */
  const entries = new Map<HTMLElement, { message_id: number; is_user: boolean; name: string }>();
  const ordered: HTMLElement[] = [];

  messages.forEach((message, fallback_id) => {
    const raw_id = Number(message.getAttribute('mesid'));
    const message_id = Number.isFinite(raw_id) ? raw_id : fallback_id;
    const source = (context?.chat ?? [])[message_id] as Message | undefined;
    const is_user = source?.is_user === true;
    const name = is_user ? '我' : source?.name || '旁白';
    for (const paragraph of paragraph_elements(text_container(message))) {
      entries.set(paragraph, { message_id, is_user, name });
      ordered.push(paragraph);
    }
  });

  if (!ordered.length) {
    toast('这个聊天里还没有可以截的正文');
    return;
  }

  const selected = new Set<HTMLElement>();
  // 楼层模式直接点楼层收藏，不会同时选中多段。
  let unit: PickUnit = 'paragraph';
  const message_set = new Set(messages);
  const disposers: Array<() => void> = [];
  let preview: HTMLElement | null = null;
  let preview_url: string | null = null;
  let result: ShotRenderResult | null = null;
  let title = '';
  let busy = false;

  /* ---------------------------------------------------------- 顶栏 */

  const is_text = options.mode === 'text';
  const count_node = el('div', { class: 'yj-shotbar__count', text: '点段落选中' });
  const cancel_button = el('button', {
    class: 'yj-btn yj-btn--ghost yj-shotbar__btn',
    text: '取消',
    attrs: { type: 'button' },
  });
  const confirm_button = el('button', {
    class: 'yj-btn yj-btn--primary yj-shotbar__btn',
    text: is_text ? '收藏' : '生成截图',
    attrs: { type: 'button' },
  });
  const unit_paragraph = el('button', {
    class: 'yj-chip yj-shotbar__unit',
    text: '段落',
    attrs: { type: 'button' },
  });
  const unit_floor = el('button', {
    class: 'yj-chip yj-shotbar__unit',
    text: '整层',
    attrs: { type: 'button' },
  });
  const unit_switch = el('div', { class: 'yj-chips yj-shotbar__units' }, [unit_paragraph, unit_floor]);

  const bar = el('div', { class: 'yj-shotbar' }, [
    count_node,
    unit_switch,
    el('div', { class: 'yj-shotbar__actions' }, [cancel_button, confirm_button]),
  ]);
  layer.append(bar);

  function sync_bar(): void {
    // 出图只能按段落挑，所以楼层切换只在文本收藏时出现。
    unit_switch.style.display = is_text ? '' : 'none';
    unit_paragraph.classList.toggle('is-active', unit === 'paragraph');
    unit_floor.classList.toggle('is-active', unit === 'floor');

    if (is_text && unit === 'floor') {
      count_node.textContent = '点楼层直接收藏';
      confirm_button.textContent = '收藏';
      confirm_button.setAttribute('disabled', 'true');
      return;
    }

    const action = is_text ? '收藏' : '生成截图';
    count_node.textContent = selected.size ? `已选 ${selected.size} 段` : '点段落选中';
    confirm_button.textContent = selected.size ? `${action}（${selected.size} 段）` : action;
    if (selected.size) confirm_button.removeAttribute('disabled');
    else confirm_button.setAttribute('disabled', 'true');
  }

  /* ---------------------------------------------------------- 选中逻辑 */

  function picked_blocks(): PickedBlock[] {
    const by_message = new Map<number, PickedBlock>();
    for (const element of ordered) {
      if (!selected.has(element)) continue;
      const meta = entries.get(element);
      // 段落取的是渲染后的文字，标签早没了；这里主要防个别没渲染成功的标签露出壳。
      const text = clean_text(element.textContent ?? '', prefs.clean_tags);
      if (!meta || !text) continue;
      const shaped =
        prefs.shot_replace_enabled && prefs.shot_replace_rules.length
          ? apply_replace_rules(text, prefs.shot_replace_rules)
          : text;
      const existing = by_message.get(meta.message_id);
      // 同一楼里挑中的段落按原顺序接成一段连续文字。
      if (existing) existing.text = `${existing.text}\n\n${shaped}`;
      else
        by_message.set(meta.message_id, {
          message_id: meta.message_id,
          is_user: meta.is_user,
          name: meta.name,
          text: shaped,
        });
    }
    return [...by_message.values()].sort((lhs, rhs) => lhs.message_id - rhs.message_id);
  }

  function toggle(element: HTMLElement): void {
    if (selected.has(element)) {
      selected.delete(element);
      element.classList.remove(PICKED_CLASS);
    } else {
      selected.add(element);
      element.classList.add(PICKED_CLASS);
    }
    sync_bar();
  }

  function find_paragraph(target: EventTarget | null): HTMLElement | null {
    let node: Node | null = target instanceof Node ? target : null;
    while (node) {
      if (node instanceof HTMLElement && entries.has(node)) return node;
      node = node.parentNode;
    }
    return null;
  }

  /** 从点击位置往上找，看落在哪一层楼层里。 */
  function find_message(target: EventTarget | null): HTMLElement | null {
    let node: Node | null = target instanceof Node ? target : null;
    while (node) {
      if (node instanceof HTMLElement && message_set.has(node)) return node;
      node = node.parentNode;
    }
    return null;
  }

  function on_click(event: Event): void {
    if (is_text && unit === 'floor') {
      const message = find_message(event.target);
      if (!message) return;
      event.preventDefault();
      event.stopPropagation();
      const raw_id = Number(message.getAttribute('mesid'));
      void collect_floor(Number.isFinite(raw_id) ? raw_id : messages.indexOf(message));
      return;
    }
    const element = find_paragraph(event.target);
    if (!element) return;
    event.preventDefault();
    event.stopPropagation();
    toggle(element);
  }

  disposers.push(on<Event>(root, 'click', on_click, true));

  /* ---------------------------------------------------------- 预览 */

  function close_preview(): void {
    if (preview_url) URL.revokeObjectURL(preview_url);
    preview_url = null;
    preview?.remove();
    preview = null;
  }

  function show_error(message: string): void {
    close_preview();
    const head = el('div', { class: 'yj-panel__bar' }, [
      back_button(() => {
        close_preview();
      }),
      el('div', { class: 'yj-panel__title', text: '生成截图' }),
    ]);
    preview = el('div', { class: 'yj-panel yj-shot-preview' }, [
      head,
      el('div', { class: 'yj-shot-preview__body' }, [
        el('div', { class: 'yj-empty' }, [
          el('div', { class: 'yj-empty__mark', html: icon('camera', 30) }),
          el('div', { class: 'yj-empty__text', text: message }),
        ]),
      ]),
    ]);
    layer.append(preview);
  }

  function back_button(on_click: () => void): HTMLElement {
    const button = el('button', {
      class: 'yj-iconbtn yj-ws__back',
      html: icon('back', 19),
      title: '返回重挑',
      attrs: { type: 'button', 'aria-label': '返回重挑' },
    });
    on<Event>(button, 'click', on_click);
    return button;
  }

  /** 文本模式：挑中的段落按顺序接成一条文本收藏。 */
  async function collect_text(): Promise<void> {
    const picked = picked_blocks();
    if (!picked.length) {
      toast('挑中的段落没有正文');
      return;
    }
    const content = picked.map(item => item.text).join('\n\n');
    const name = await prompt_dialog({
      title: '给这条收藏起个标题',
      message: excerpt(content, 60),
      confirm_text: '收藏',
      input: { placeholder: '例如：雨夜的对话' },
    });
    if (name === null) return;
    try {
      await store.put_text({
        id: store.new_id(),
        character_key,
        title: name || '未命名',
        content,
        created_at: Date.now(),
        // 只挑了一层就记下楼层号，跨层挑的话没法记。
        source_message_id: picked.length === 1 ? picked[0].message_id : null,
      });
      toast('已收藏');
      stop();
    } catch (failure) {
      console.warn('[月季管家] 收藏文本失败', failure);
      toast('收藏失败');
    }
  }

  /**
   * 整层收藏。取楼层原始文本而不是渲染后的 DOM，
   * 这样清洗标签才能把 <标签> 连同里面的内容一起抹掉。
   */
  async function collect_floor(message_id: number): Promise<void> {
    const source = (context?.chat ?? [])[message_id] as Message | undefined;
    const raw = typeof source?.mes === 'string' ? source.mes : '';
    const cleaned = clean_text(raw, prefs.clean_tags);
    if (!cleaned) {
      toast(prefs.clean_tags.length ? '这层按清洗标签过滤之后没有剩下正文' : '这层没有可以收藏的正文');
      return;
    }
    const name = await prompt_dialog({
      title: `收藏第 ${message_id + 1} 层`,
      message: excerpt(cleaned, 70),
      confirm_text: '收藏',
      input: { placeholder: '起个标题（可不填）' },
    });
    if (name === null) return;
    try {
      await store.put_text({
        id: store.new_id(),
        character_key,
        title: name || `第 ${message_id + 1} 层`,
        content: cleaned,
        created_at: Date.now(),
        source_message_id: message_id,
      });
      toast('已收藏整层');
      stop();
    } catch (failure) {
      console.warn('[月季管家] 收藏整层失败', failure);
      toast('收藏失败');
    }
  }

  async function run_render(): Promise<void> {
    const blocks: ShotBlock[] = picked_blocks().map(item => ({
      name: item.name,
      text: item.text,
      is_user: item.is_user,
    }));
    if (!blocks.length) {
      toast('挑中的段落没有正文');
      return;
    }
    busy = true;
    confirm_button.textContent = '正在生成';
    confirm_button.setAttribute('disabled', 'true');
    try {
      result = await render_shot({
        blocks,
        style: SHOT_STYLE,
        title,
        footer: `${character_name}  ${new Date().toLocaleDateString('zh-CN')}`,
        theme: resolve_shot_theme(prefs.shot_theme, prefs.shot_background, prefs.shot_ink),
        background_image:
          prefs.shot_theme === 'image' && prefs.shot_background_image
            ? { source: prefs.shot_background_image, mode: prefs.shot_background_mode }
            : undefined,
        body_font: shot_font_family(),
      });
      show_preview();
    } catch (failure) {
      console.warn('[月季管家] 生成截图失败', failure);
      show_error(failure instanceof Error ? failure.message : '生成图片失败。');
    }
    busy = false;
    confirm_button.removeAttribute('disabled');
    sync_bar();
  }

  function show_preview(): void {
    close_preview();
    if (!result?.blob) {
      show_error('图片没有生成成功。');
      return;
    }
    preview_url = URL.createObjectURL(result.blob);

    const save_local = el('button', {
      class: 'yj-btn yj-btn--ghost',
      text: '保存到本地',
      attrs: { type: 'button' },
    });
    on<Event>(save_local, 'click', () => {
      if (!result?.blob) return;
      download_blob(result.blob, shot_filename(title || character_name));
      toast('已生成图片，看看浏览器的下载');
    });

    const collect = el('button', {
      class: 'yj-btn yj-btn--primary',
      text: '收进图库',
      attrs: { type: 'button' },
    });
    on<Event>(collect, 'click', () => {
      void collect_to_library();
    });

    const close = el('button', {
      class: 'yj-iconbtn yj-panel__close',
      html: icon('close', 19),
      title: '关闭',
      attrs: { type: 'button', 'aria-label': '关闭' },
    });
    on<Event>(close, 'click', () => {
      stop();
    });

    const title_input = el('input', {
      class: 'yj-input',
      attrs: { type: 'text', placeholder: '给这张图起个标题（可不填）', value: title },
    });
    on<Event>(title_input, 'input', () => {
      title = title_input.value;
    });

    const parts: HTMLElement[] = [
      el('div', { class: 'yj-panel__bar' }, [
        back_button(() => {
          close_preview();
        }),
        el('div', { class: 'yj-panel__title', text: '截图预览' }),
        el('div', { class: 'yj-panel__actions' }, [close]),
      ]),
      el('div', { class: 'yj-shot-preview__body' }, [
        el('div', { class: 'yj-preview' }, [
          el('img', { class: 'yj-preview__image', attrs: { src: preview_url, alt: '截图预览' } }),
        ]),
        el('div', {
          class: 'yj-row__meta',
          text: `${result.width}  ${result.height} 像素  ${selected.size} 段`,
        }),
      ]),
    ];

    if (result.truncated) {
      parts.push(
        el('div', { class: 'yj-shot-preview__note' }, [
          el('div', {
            class: 'yj-note yj-note--warn',
            text: '内容太长，这台设备一次画不完。图里只放了前面一部分，想要完整图请少挑几段分两次截。',
          }),
        ]),
      );
    }

    parts.push(
      el('div', { class: 'yj-shot-preview__foot' }, [
        title_input,
        el('div', { class: 'yj-detail__actions' }, [save_local, collect]),
      ]),
    );

    preview = el('div', { class: 'yj-panel yj-shot-preview' }, parts);
    layer.append(preview);
  }

  async function collect_to_library(): Promise<void> {
    if (!result?.blob) return;
    let name = title.trim();
    if (!name) {
      const answer = await prompt_dialog({
        title: '给这张截图起个标题',
        confirm_text: '收藏',
        input: { placeholder: '例如：雨夜的对话' },
      });
      if (answer === null) return;
      name = answer || '未命名';
      title = name;
    }
    try {
      await store.put_shot(
        {
          id: store.new_id(),
          character_key,
          title: name,
          created_at: Date.now(),
          width: result.width,
          height: result.height,
          bytes: result.blob.size,
          starred: false,
          thumb: result.thumb,
        },
        result.blob,
      );
      toast('已收进图库');
      stop();
    } catch (failure) {
      console.warn('[月季管家] 收藏截图失败', failure);
      toast('收藏失败');
    }
  }

  /* ---------------------------------------------------------- 进出模式 */

  function stop(): void {
    for (const dispose of disposers) dispose();
    disposers.length = 0;
    for (const element of selected) element.classList.remove(PICKED_CLASS);
    selected.clear();
    document.body.classList.remove(MODE_CLASS);
    close_preview();
    bar.remove();
    options.on_leave?.();
  }

  on<Event>(cancel_button, 'click', () => {
    stop();
  });
  on<Event>(confirm_button, 'click', () => {
    if (busy) return;
    if (is_text && unit === 'floor') {
      toast('整层收藏是点楼层，不用按这个按钮');
      return;
    }
    if (is_text) void collect_text();
    else void run_render();
  });
  on<Event>(unit_paragraph, 'click', () => {
    unit = 'paragraph';
    sync_bar();
  });
  on<Event>(unit_floor, 'click', () => {
    unit = 'floor';
    selected.forEach(element => element.classList.remove(PICKED_CLASS));
    selected.clear();
    sync_bar();
  });
  disposers.push(
    on<KeyboardEvent>(document, 'keydown', event => {
      if (event.key !== 'Escape') return;
      event.stopPropagation();
      if (preview) close_preview();
      else stop();
    }),
  );

  // 先加 class 再回调，否则外部判断「是不是在挑段落模式」时拿到的还是旧状态。
  document.body.classList.add(MODE_CLASS);
  sync_bar();
  options.on_enter?.();
}
