import { shadow_layer } from './dom';

/**
 * 字体库。
 *
 * 内置几款常见中文字体，另外允许作者粘贴自己的字体定义（@import / @font-face）保存成命名条目。
 *
 * 关于注入：字体定义必须挂在文档上，画布和界面才用得上，所以确实要往页面里注入样式。
 * 但只注入 @import 与 @font-face  这两个只是「定义字体」，不会作用到任何元素。
 * 作者粘进来的其他规则（例如 body { font-family: ... }）一律丢掉，绝不动酒馆本身的字体。
 */

export interface FontChoice {
  id: string;
  name: string;
  /** 真正写进 font-family 的值。留空表示用插件默认。 */
  family: string;
  /** 需要注入到页面的样式（@import / @font-face）。 */
  css: string;
  builtin: boolean;
}

const STORAGE_KEY = 'yueji-guanjia.fonts';
const SHOT_KEY = 'yueji-guanjia.font-shot';
const TEXT_KEY = 'yueji-guanjia.font-text';
const STYLE_ID = 'yueji-guanjia-fonts';

/** 插件原本的阅读字体，作为兜底。 */
export const READ_FALLBACK = '"Songti SC", "Noto Serif SC", "Source Han Serif SC", "SimSun", serif';

/** 作者自己常用的那一套。整段原样保留，包括它带的那条全局规则。 */
const YUANYUE_CSS = `@import url('https://fontsapi.zeoseven.com/309/main/result.css');

@font-face {
  font-family: 'Times New Roman Custom';
  src: url('https://shswy.qzz.io/file/1782232297274_Times_New_Roman.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

body, #chat, .mes_text, .drawer-content, input, textarea, select, button {
  font-family: 'Times New Roman Custom', 'KingHwaOldSong', serif;
}`;

export const BUILTIN_FONTS: FontChoice[] = [
  { id: 'default', name: '插件默认', family: '', css: '', builtin: true },
  {
    id: 'songti',
    name: '宋体',
    family: '"Songti SC", "SimSun", "Noto Serif SC", serif',
    css: '',
    builtin: true,
  },
  {
    id: 'kaiti',
    name: '楷体',
    family: '"Kaiti SC", "KaiTi", "STKaiti", "楷体", serif',
    css: '',
    builtin: true,
  },
  {
    id: 'heiti',
    name: '黑体',
    family: '"Heiti SC", "SimHei", "PingFang SC", "Microsoft YaHei", sans-serif',
    css: '',
    builtin: true,
  },
  {
    id: 'yuanyue',
    name: '月月特供版',
    family: "'Times New Roman Custom', 'KingHwaOldSong', serif",
    css: YUANYUE_CSS,
    builtin: true,
  },
];

export function load_custom_fonts(): FontChoice[] {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((item): item is Partial<FontChoice> => Boolean(item) && typeof item === 'object')
      .filter(item => typeof item.id === 'string' && typeof item.name === 'string')
      .map(item => ({
        id: String(item.id),
        name: String(item.name),
        family: typeof item.family === 'string' ? item.family : '',
        css: typeof item.css === 'string' ? item.css : '',
        builtin: false,
      }));
  } catch (error) {
    console.warn('[月季管家] 读取字体库失败', error);
    return [];
  }
}

export function save_custom_fonts(list: FontChoice[]): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(list.filter(item => !item.builtin)));
  } catch (error) {
    console.warn('[月季管家] 保存字体库失败', error);
  }
}

export function all_fonts(): FontChoice[] {
  return [...BUILTIN_FONTS, ...load_custom_fonts()];
}

export function find_font(id: string): FontChoice | undefined {
  return all_fonts().find(item => item.id === id);
}

export function load_font_id(which: 'shot' | 'text'): string {
  try {
    const raw = window.localStorage.getItem(which === 'shot' ? SHOT_KEY : TEXT_KEY);
    if (!raw) return 'default';
    // 字体被删掉之后退回默认，避免用一个不存在的字体。
    return find_font(raw) ? raw : 'default';
  } catch (error) {
    console.warn('[月季管家] 读取字体选择失败', error);
    return 'default';
  }
}

export function save_font_id(which: 'shot' | 'text', id: string): void {
  try {
    window.localStorage.setItem(which === 'shot' ? SHOT_KEY : TEXT_KEY, id);
  } catch (error) {
    console.warn('[月季管家] 保存字体选择失败', error);
  }
}

/**
 * 只挑出字体定义，其余规则全部丢掉。
 *
 * 保留 @import url(...); 与 @font-face { ... }。
 * 这两者只声明字体、不套用到任何元素，所以不会影响酒馆本身的排版。
 * 作者粘进来的全局规则（body/#chat/.mes_text 之类）会被丢掉。
 */
export function font_definitions_only(css: string): string {
  const kept = css.match(/@(?:import\s[^;]*;|font-face\s*\{[^}]*\})/gi);
  return kept ? kept.join('\n') : '';
}

/**
 * 从粘贴的样式里猜出 font-family。
 * 取最后一条 font-family  作者通常把总字体写在最后那条全局规则里。
 */
export function extract_family(css: string): string {
  const matches = [...css.matchAll(/font-family\s*:\s*([^;}]+)/gi)];
  const last = matches.at(-1)?.[1];
  return last ? last.trim().replace(/\s*!important\s*$/i, '') : '';
}

/** 把用到的字体样式注入页面，并把阅读字体挂到插件内容层上。 */
export function apply_fonts(): void {
  const shot = find_font(load_font_id('shot'));
  const text = find_font(load_font_id('text'));
  // 只注入字体定义本身，作者粘的全局规则不进页面。
  const css = [shot?.css, text?.css]
    .filter(Boolean)
    .map(item => font_definitions_only(item ?? ''))
    .filter(Boolean)
    .join('\n\n');

  let style = document.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!css) {
    style?.remove();
  } else {
    if (!style) {
      style = document.createElement('style');
      style.id = STYLE_ID;
      document.head.append(style);
    }
    style.textContent = css;
  }

  const layer = shadow_layer();
  if (layer) layer.style.setProperty('--yj-font-read', text?.family || READ_FALLBACK);
}

/** 出图时用的正文字体。 */
export function shot_font_family(): string {
  return find_font(load_font_id('shot'))?.family || '';
}

export function new_font_id(): string {
  return `font-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}
