/**
 * 搜索与过滤。
 * 按作者选择：只做简单字符串匹配，不引入分词和正则。
 */

/** 关键词是否命中任意一个字段。关键词为空时一律算命中。 */
export function matches_keyword(keyword: string, ...fields: Array<string | null | undefined>): boolean {
  const needle = keyword.trim().toLowerCase();
  if (!needle) return true;
  return fields.some(field => typeof field === 'string' && field.toLowerCase().includes(needle));
}

/**
 * 把一段文本按给定规则替换，用于截图出图前。
 * 和文本侧的 replace_words 行为一致，只是调用时机不同：这个是出图前改内容。
 */
export function apply_replace_rules(text: string, rules: Array<{ from: string; to: string }>): string {
  let result = text;
  for (const rule of rules) {
    if (!rule.from) continue;
    result = result.split(rule.from).join(rule.to);
  }
  return result;
}

/** 把一段文本按给定规则做替换，用于文本收藏的「替换名词」。 */
export function replace_words(text: string, rules: Array<{ from: string; to: string }>): string {
  let result = text;
  for (const rule of rules) {
    if (!rule.from) continue;
    result = result.split(rule.from).join(rule.to);
  }
  return result;
}

/** 收尾：把空格造成的空行和首尾空白理一理。 */
function tidy(text: string): string {
  return text
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/** 把用户写的标签名规整成纯标签名，允许写成 <foo> 或 foo。 */
function normalize_tag(raw: string): string {
  return raw.trim().replace(/^</, '').replace(/>$/, '').trim();
}

function escape_reg_exp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * 按清洗标签丢掉楼层里的结构，只留标签外的正文。
 *
 * 三种写法都会处理：成对标签、自闭合标签、以及没配对上的孤立开标签。
 * 这样即使模型输出的结构不完整，也不会把整段正文留下或者整段删光。
 */
export function strip_tags(text: string, tags: string[]): string {
  let result = text;
  for (const raw of tags) {
    const tag = normalize_tag(raw);
    if (!tag) continue;
    const name = escape_reg_exp(tag);
    // 标签名后面必须是空白、斜杠或右尖括号。
    // 不能用 \b：词边界只认 ASCII 字母数字，中文标签名（例如「时间」）永远匹配不上。
    const open = `<${name}(?=[\\s/>])[^>]*>`;
    result = result.replace(new RegExp(`${open}[\\s\\S]*?<\\/${name}>`, 'gi'), '');
    result = result.replace(new RegExp(`<${name}(?=[\\s/>])[^>]*\\/>`, 'gi'), '');
    result = result.replace(new RegExp(open, 'gi'), '');
  }
  return tidy(result);
}

/** 标签名的第一个字符：中英文都算，避免把「a < b」这种正文误当成标签。 */
const MARKUP = /<\/?[a-zA-Z\u4e00-\u9fa5][^>]*>/g;

/**
 * 只脱掉标签本体，保留标签之间的文字。
 *
 * 这是默认行为：收藏文本里不该出现 `<xxx>` 这种壳，
 * 但里面的内容有人是想留着的，所以不主动删。
 * 真正想让某个标签连内容一起不渲染，就把它写进清洗标签。
 */
export function strip_markup(text: string): string {
  return text.replace(MARKUP, '');
}

/**
 * 收藏文本前统一的清洗。
 *
 * 两级：
 * 1. 清洗标签里的标签，连内容一起抹掉（例如 <时间>22:10</时间> 整段不要）。
 * 2. 剩下的标签只脱壳，里面的文字留着（例如 <高亮>重点</高亮> 变成「重点」）。
 *
 * 顺序不能反：先脱壳的话，清洗标签就匹配不到了。
 */
export function clean_text(text: string, clean_tags: string[]): string {
  return tidy(strip_markup(clean_tags.length ? strip_tags(text, clean_tags) : text));
}
/**
 * 把一段楼层正文切成段落，供截图时逐段挑选。
 *
 * 优先按空行切。如果整段没有空行、但本身是多行的，就按单个换行切，
 * 免得一整层只能整体选中、挑不出中间那几段。
 */
export function split_paragraphs(text: string): string[] {
  const by_blank = text
    .split(/\n[ \t]*\n/)
    .map(part => part.trim())
    .filter(Boolean);
  if (by_blank.length > 1) return by_blank;
  const by_line = text
    .split(/\n/)
    .map(part => part.trim())
    .filter(Boolean);
  return by_line.length ? by_line : [];
}
