import { avatar_key, NO_CHARACTER } from '../../core/types';
import type { TavernContext } from '../../tavern/env';
import { arrange, is_pinned, load_order, pin, save_order, unpin } from '../character_order';
import { el, on } from '../dom';
import { icon } from '../icons';
import { toast } from '../toast';

/** 角色页。支持按名字搜索、置顶、以及拖动调整顺序。 */

export interface CharactersHandlers {
  on_open: (character_key: string, title: string) => void;
}

interface Row {
  key: string;
  name: string;
  is_current: boolean;
}

export function render_characters(context: TavernContext | null, handlers: CharactersHandlers): HTMLElement {
  const characters = context?.characters ?? [];

  if (!characters.length) {
    return el('section', { class: 'yj-page' }, [
      el('div', { class: 'yj-empty' }, [
        el('div', { class: 'yj-empty__mark', html: icon('user', 30) }),
        el('div', { class: 'yj-empty__text', text: '现在读不到角色卡列表，或者酒馆里还没有角色。' }),
      ]),
    ]);
  }

  let keyword = '';
  let sorting = false;

  const index_of_avatar = (index: number): string => {
    const avatar = characters[index]?.avatar;
    return typeof avatar === 'string' && avatar ? avatar_key(avatar) : NO_CHARACTER;
  };

  const current_key = (() => {
    const index = Number(context?.characterId);
    return Number.isFinite(index) ? index_of_avatar(index) : NO_CHARACTER;
  })();

  function all_rows(): Row[] {
    const keys = characters.map((_, index) => index_of_avatar(index));
    return arrange(keys, load_order()).map(key => {
      const index = keys.indexOf(key);
      return { key, name: characters[index]?.name || '未命名角色', is_current: key === current_key };
    });
  }

  /* ---------------------------------------------------------- 部件 */

  const search = el('input', {
    class: 'yj-search__input',
    attrs: { type: 'search', placeholder: '搜索角色名', enterkeyhint: 'search' },
  });
  const sort_button = el('button', {
    class: 'yj-btn yj-btn--ghost yj-sortbar__btn',
    attrs: { type: 'button' },
  });
  const search_row = el('div', { class: 'yj-search' }, [
    el('div', { class: 'yj-search__icon', html: icon('search', 17) }),
    search,
    sort_button,
  ]);

  const list = el('div', { class: 'yj-card yj-char-list' });
  const no_match = el('div', { class: 'yj-empty__text', text: '没有匹配的角色。' });
  const hint = el('div', { class: 'yj-note' });

  /* ---------------------------------------------------------- 拖动排序 */

  let dragging: HTMLElement | null = null;
  let active_pointer: number | null = null;
  let start_y = 0;

  function commit_order(): void {
    const keys = [...list.querySelectorAll<HTMLElement>('[data-key]')]
      .map(element => element.dataset.key ?? '')
      .filter(Boolean);
    save_order({ ...load_order(), order: keys });
  }

  function on_pointer_down(event: PointerEvent, row: HTMLElement): void {
    if (!sorting) return;
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    active_pointer = event.pointerId;
    dragging = row;
    start_y = event.clientY;
    row.classList.add('is-dragging');
    if (typeof row.setPointerCapture === 'function') row.setPointerCapture(event.pointerId);
    window.addEventListener('pointermove', on_pointer_move);
    window.addEventListener('pointerup', on_pointer_up);
    window.addEventListener('pointercancel', on_pointer_cancel);
    event.preventDefault();
  }

  function stop_tracking(): void {
    window.removeEventListener('pointermove', on_pointer_move);
    window.removeEventListener('pointerup', on_pointer_up);
    window.removeEventListener('pointercancel', on_pointer_cancel);
  }

  function on_pointer_cancel(event: PointerEvent): void {
    if (active_pointer !== event.pointerId) return;
    stop_tracking();
    if (dragging) {
      dragging.classList.remove('is-dragging');
      dragging.style.transform = '';
    }
    dragging = null;
    active_pointer = null;
  }

  function on_pointer_move(event: PointerEvent): void {
    if (active_pointer !== event.pointerId || !dragging) return;
    const pointer_y = event.clientY;
    dragging.style.transform = `translateY(${pointer_y - start_y}px)`;

    const next = dragging.nextElementSibling as HTMLElement | null;
    if (next && pointer_y > next.getBoundingClientRect().top + next.offsetHeight / 2) {
      // 把下一行挪到这行前面，等于这行下移一格；基准跟着移，视觉上才黏手指。
      list.insertBefore(next, dragging);
      start_y += next.offsetHeight;
      dragging.style.transform = `translateY(${pointer_y - start_y}px)`;
      return;
    }
    const previous = dragging.previousElementSibling as HTMLElement | null;
    if (previous && pointer_y < previous.getBoundingClientRect().top + previous.offsetHeight / 2) {
      list.insertBefore(dragging, previous);
      start_y -= previous.offsetHeight;
      dragging.style.transform = `translateY(${pointer_y - start_y}px)`;
    }
  }

  function on_pointer_up(event: PointerEvent): void {
    if (active_pointer !== event.pointerId || !dragging) return;
    stop_tracking();
    if (typeof dragging.hasPointerCapture === 'function' && dragging.hasPointerCapture(event.pointerId)) {
      dragging.releasePointerCapture(event.pointerId);
    }
    dragging.classList.remove('is-dragging');
    dragging.style.transform = '';
    dragging = null;
    active_pointer = null;
    commit_order();
    toast('顺序已保存');
  }

  /* ---------------------------------------------------------- 行 */

  function build_row(row: Row): HTMLElement {
    const pinned = is_pinned(row.key, load_order());
    const pin_button = el('button', {
      class: `yj-iconbtn yj-row__pin${pinned ? ' is-on' : ''}`,
      html: icon('pin', 17),
      title: pinned ? '取消置顶' : '置顶',
      attrs: { type: 'button', 'aria-label': '置顶' },
    });
    on<Event>(pin_button, 'click', event => {
      event.stopPropagation();
      const keys = all_rows().map(item => item.key);
      const saved = load_order();
      save_order(pinned ? unpin(row.key, saved) : pin(row.key, keys, saved));
      render_list();
      toast(pinned ? '已取消置顶' : '已置顶');
    });

    const element = el('div', { class: 'yj-row', attrs: { 'data-key': row.key } }, [
      el('div', { class: 'yj-row__main' }, [
        el('div', { class: 'yj-row__title', text: row.name }),
        el('div', { class: 'yj-row__meta', text: row.is_current ? '当前角色' : '进入收藏库' }),
      ]),
      sorting ? el('div', { class: 'yj-row__grip', html: icon('grip', 18) }) : pin_button,
    ]);
    if (row.is_current) element.classList.add('is-current');
    if (pinned) element.classList.add('is-pinned');

    if (sorting) {
      element.classList.add('yj-row--draggable');
      on<PointerEvent>(element, 'pointerdown', event => {
        on_pointer_down(event, element);
      });
    } else {
      element.classList.add('yj-row--tappable');
      on<Event>(element, 'click', () => {
        handlers.on_open(row.key, row.name);
      });
    }
    return element;
  }

  /* ---------------------------------------------------------- 渲染 */

  function render_list(): void {
    const needle = keyword.trim().toLowerCase();
    const rows = all_rows().filter(row => !needle || row.name.toLowerCase().includes(needle));
    list.replaceChildren(...rows.map(build_row));
    list.style.display = rows.length ? '' : 'none';
    no_match.style.display = rows.length ? 'none' : '';
  }

  function render_chrome(): void {
    sort_button.textContent = sorting ? '完成' : '排序';
    search.style.display = sorting ? 'none' : '';
    hint.textContent = sorting
      ? '按住任意一行上下拖动就能换顺序，松手自动保存。'
      : '点图钉把角色置顶。置顶的角色会排在最前面。';
  }

  on<Event>(search, 'input', () => {
    keyword = search.value;
    render_list();
  });
  on<Event>(sort_button, 'click', () => {
    sorting = !sorting;
    if (sorting) {
      // 排序时列表必须是完整的，否则拖出来的顺序是残缺的。
      keyword = '';
      search.value = '';
    }
    render_chrome();
    render_list();
  });

  const page = el('section', { class: 'yj-page' });
  page.append(search_row, hint, el('div', { class: 'yj-ws__body' }, [list, no_match]));
  render_chrome();
  render_list();
  return page;
}
